let chItems=[],chRevision=-1,chTab='library',chSettings={...CrosshairCore.defaults},chEditing=false,chSearch='';
const chE=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e};
async function chCopy(code){try{await navigator.clipboard.writeText(code);notice('准星代码已复制')}catch(e){const area=document.querySelector('#ch-code');if(area){area.focus();area.select()}notice('无法自动复制，请选中代码后手动复制',true)}}
async function chFetch(){try{const d=await api('crosshairs');chItems=d.items;chRevision=d.revision}catch(e){if(chRevision<0){const r=await fetch('crosshairs-seed.json');chItems=(await r.json()).items}if(!staticPreview)notice('当前为离线浏览；管理员维护需要连接服务',true)}}
async function showCrosshairs(tab=chTab){document.body.dataset.page='crosshairs';page='crosshairs';mapObserver?.disconnect();chTab=tab;document.title='准星设置 · 森希Valorant';root.innerHTML='<div class="brand-section"><span>森希Valorant / 准星设置</span></div><h1>把焦点，留给目标。</h1><p>挑选准星、微调样式，再把代码带进游戏。</p><div id="ch-tabs" class="toolbar" role="tablist" aria-label="准星功能"></div><section id="ch-content"></section>';for(const [id,label]of [['library','准星库'],['generator','准星生成器'],['guide','准星设置教程']]){const b=chE('button',label);b.type='button';b.role='tab';b.setAttribute('aria-selected',String(id===tab));b.className=id===tab?'active':'';b.onclick=()=>showCrosshairs(id);document.querySelector('#ch-tabs').append(b)}if(tab==='library'){await chFetch();if(page==='crosshairs'&&chTab==='library')chLibrary()}else if(tab==='generator')chGenerator();else chGuide()}
function chLibrary(){const root=document.querySelector('#ch-content');root.replaceChildren();const tools=chE('div',undefined,'toolbar'),search=chE('input');search.placeholder='搜索准星名称或说明';search.setAttribute('aria-label','搜索准星');search.value=chSearch;tools.append(search);if(admin){const add=chE('button','新增准星');add.onclick=()=>chEdit();tools.append(add)}root.append(tools);const grid=chE('div',undefined,'ch-grid');root.append(grid);function draw(){grid.replaceChildren();const items=chItems.filter(i=>(admin||i.published)&&(i.name+' '+i.description).toLowerCase().includes(chSearch.toLowerCase()));if(!items.length)grid.append(chE('p','未找到准星，换个关键词或由管理员新增。'));for(const i of items){const card=chE('article',undefined,'panel ch-card'),preview=chE('div',undefined,'ch-preview');card.dataset.crosshairId=i.id;try{preview.innerHTML=CrosshairCore.svg(CrosshairCore.parse(i.code).settings,3)}catch(e){preview.textContent='此代码暂不支持预览，请在游戏内查看'}card.append(preview,chE('h3',i.name),chE('p',i.description),chE('span',i.published?'已发布':'管理员草稿','muted'));if(i.media?.length){const gallery=chE('div',undefined,'ch-gallery');for(const f of i.media){const a=chE('a'),img=chE('img');a.href=f.url;a.target='_blank';a.rel='noopener';img.src=f.url;img.alt=i.name+'准星截图';img.loading='lazy';a.append(img);gallery.append(a)}card.append(gallery)}const code=chE('textarea');code.value=i.code;code.readOnly=true;code.setAttribute('aria-label',i.name+'代码');card.append(code);const actions=chE('div',undefined,'toolbar'),copy=chE('button','复制代码'),load=chE('button','载入生成器');copy.onclick=()=>{window.Toolbox?.remember('crosshair:'+i.id);chCopy(i.code)};load.onclick=()=>{try{const parsed=CrosshairCore.parse(i.code);if(parsed.warnings.length&&!confirm(parsed.warnings.join('；')+'。继续仅编辑支持的主准星参数？'))return;window.Toolbox?.remember('crosshair:'+i.id);chSettings={...parsed.settings,c:parsed.settings.c===8?5:parsed.settings.c};showCrosshairs('generator')}catch(e){notice(e.message,true)}};actions.append(copy,load);if(admin){const edit=chE('button','编辑准星');edit.onclick=()=>chEdit(i);actions.append(edit)}card.append(actions);grid.append(card)}}search.oninput=()=>{chSearch=search.value;draw()};draw()}
function chGenerator(){const c=document.querySelector('#ch-content');c.innerHTML='<div class="ch-generator"><section class="panel"><h2>主准星预览</h2><div id="ch-preview" class="ch-preview ch-large"></div><label>预览背景<select id="ch-background"><option value="dark">深色场景</option><option value="sand">浅色场景</option><option value="map">地图俯视图</option></select></label><label>预览倍率<select id="ch-zoom"><option value="1">1倍</option><option value="2">2倍</option><option value="4" selected>4倍</option></select></label><p class="muted">网页显示主准星静态示意；移动与射击误差写入代码，动态表现请在游戏内测试。A/S瞄准镜配置不参与生成。</p><label>生成的配置代码<textarea id="ch-code" readonly></textarea></label><div class="toolbar"><button id="ch-copy">复制代码</button><button id="ch-reset">重置</button></div><label>导入已有代码<textarea id="ch-import" placeholder="0;P;…"></textarea></label><button id="ch-parse">读取主准星</button><p id="ch-warnings" class="warning" hidden></p></section><section class="panel" id="ch-controls"><h2>调整参数</h2></section></div>';const controls=document.querySelector('#ch-controls');const labels={c:'准星颜色',h:'启用轮廓',t:'轮廓粗细',o:'轮廓透明度',d:'启用中心点',z:'中心点大小',a:'中心点透明度','0b':'启用内线','0l':'内线长度','0t':'内线粗细','0o':'内线间距','0a':'内线透明度','0m':'内线移动误差','0f':'内线射击误差','1b':'启用外线','1l':'外线长度','1t':'外线粗细','1o':'外线间距','1a':'外线透明度','1m':'外线移动误差','1f':'外线射击误差'};function update(){document.querySelector('#ch-preview').innerHTML=CrosshairCore.svg(chSettings,Number(document.querySelector('#ch-zoom').value));document.querySelector('#ch-code').value=CrosshairCore.encode(chSettings)}for(const [k,label]of Object.entries(labels)){const l=chE('label',label, 'ch-control');let input;if(k==='c'){input=chE('select');['白色','绿色','黄绿色','绿黄色','黄色','青色','粉色','红色'].forEach((v,i)=>{const o=chE('option',v);o.value=i;input.append(o)})}else{input=chE('input');const[min,max,step]=CrosshairCore.ranges[k];input.type=max===1&&step===1?'checkbox':'range';input.min=min;input.max=max;input.step=step}input.name=k;input.setAttribute('aria-label',label);if(input.type==='checkbox')input.checked=!!chSettings[k];else input.value=chSettings[k];const value=chE('output',String(chSettings[k]));input.oninput=()=>{chSettings[k]=input.type==='checkbox'?Number(input.checked):Number(input.value);value.textContent=chSettings[k];update()};l.append(input,value);controls.append(l)}document.querySelector('#ch-copy').onclick=()=>chCopy(document.querySelector('#ch-code').value);document.querySelector('#ch-reset').onclick=()=>{chSettings={...CrosshairCore.defaults};chGenerator()};document.querySelector('#ch-zoom').onchange=update;document.querySelector('#ch-background').onchange=e=>{const preview=document.querySelector('#ch-preview');preview.dataset.bg=e.target.value;if(e.target.value==='map')preview.style.backgroundImage='url('+maps[0].displayIcon+')';else preview.style.backgroundImage='none'};document.querySelector('#ch-parse').onclick=()=>{try{const parsed=CrosshairCore.parse(document.querySelector('#ch-import').value.trim());if(parsed.warnings.length&&!confirm(parsed.warnings.join('；')+'。继续？'))return;chSettings={...parsed.settings,c:parsed.settings.c===8?5:parsed.settings.c};chGenerator();if(parsed.warnings.length){const w=document.querySelector('#ch-warnings');w.hidden=false;w.textContent=parsed.warnings.join('；')}}catch(e){notice(e.message,true)}};update()}
function chGuide(){const c=document.querySelector('#ch-content');c.replaceChildren();for(const [title,text]of [['把代码导入游戏','复制完整代码。打开游戏设置中的“准星”，在配置区域选择导入配置代码，粘贴并确认。建议新建配置，保留原有准星。'],['从基础样式开始','先在练习场调整内线的长度、粗细和中心间距，再比较不同背景中的可见性。准星没有适用于所有人的唯一答案。'],['点状准星怎么做','关闭内线和外线，启用中心点，再调整大小和轮廓；避免把所有可见元素都关闭。'],['内线、外线与轮廓','内线构成靠近中心的形状，外线用于外围辅助标记。黑色轮廓可以帮助浅色准星在复杂场景中保持清晰。'],['动态误差与网页预览','生成器可以设置移动、射击误差开关，但此处仅预览静态形状。动态扩散、游戏分辨率及准星高级配置需在游戏中验证。'],['导入后看不到准星','检查元素开关、透明度、长度和颜色。尝试恢复基础样式后逐项调整，并确认已选中刚导入的配置。']]){const section=chE('section',undefined,'panel ch-lesson');section.append(chE('h2',title),chE('p',text));c.append(section)}const a=chE('a','参考：VALDB准星生成器');a.href='https://valdb.com/zh/crosshair-generator/';a.target='_blank';a.rel='noopener';c.append(a)}
function chEdit(existing){if(!admin)return;const dialog=document.querySelector('#ch-editor');dialog.replaceChildren();const rev=chRevision,item=existing?structuredClone(existing):{name:'',code:CrosshairCore.encode(chSettings),description:'',published:false,attachments:[]};let attachments=[...item.attachments],media=[...(item.media||[])],uploading=false,changed=false;const close=chE('button','关闭 ×');close.type='button';const cancel=()=>{if(uploading)return;if(changed&&!confirm('放弃未保存的准星修改？'))return;chEditing=false;dialog.close()};close.onclick=cancel;dialog.oncancel=e=>{e.preventDefault();cancel()};dialog.append(close,chE('h2',existing?'编辑准星':'新增准星'));const form=chE('form');form.id='ch-form';for(const[key,label,type]of [['name','准星名称','input'],['code','准星代码','textarea'],['description','说明','textarea']]){const l=chE('label',label),input=chE(type);input.name=key;input.value=item[key];input.maxLength=key==='name'?80:key==='code'?2000:1600;input.required=key!=='description';l.append(input);form.append(l)}const gallery=chE('div',undefined,'ch-gallery'),status=chE('p');status.role='status';function draw(){gallery.replaceChildren();for(const f of media){const row=chE('div'),img=chE('img'),remove=chE('button','移除截图');img.src=f.url;img.alt='准星截图';remove.type='button';remove.onclick=()=>{if(uploading)return;media=media.filter(m=>m.id!==f.id);attachments=attachments.filter(id=>id!==f.id);changed=true;chEditing=true;draw()};row.append(img,remove);gallery.append(row)}}const label=chE('label','添加截图：PNG/JPEG/WebP，≤20MB，统一1280×720，最多4张'),file=chE('input');file.type='file';file.accept='image/png,image/jpeg,image/webp';label.append(file);form.append(label,status,gallery);const publishedLabel=chE('label','公开发布'),published=chE('input');published.type='checkbox';published.checked=item.published;publishedLabel.prepend(published);form.append(publishedLabel);const error=chE('p',undefined,'error');error.role='alert';const save=chE('button','保存准星');save.type='submit';form.append(error,save);form.oninput=()=>{changed=true;chEditing=true};file.onchange=async()=>{const f=file.files[0];if(!f||uploading)return;if(f.size>20*1024*1024||attachments.length>=4){status.textContent='单张上限20MB，每个准星最多4张截图';return}uploading=true;chEditing=true;save.disabled=true;status.textContent='上传并统一图片规格中…';try{const r=await fetch('/api/media?scope=crosshairs&kind=images',{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:f});const d=await r.json();if(!r.ok)throw Error(d.error);attachments.push(d.id);media.push(d);changed=true;draw();status.textContent='截图已上传，保存准星后生效'}catch(e){status.textContent=e.message}finally{uploading=false;save.disabled=false;file.value=''}};form.onsubmit=async e=>{e.preventDefault();if(uploading)return;save.disabled=true;try{const code=form.elements.code.value.trim();CrosshairCore.parse(code);const r=await api('crosshairs',existing?'PUT':'POST',{revision:rev,id:existing?.id,item:{name:form.elements.name.value,code,description:form.elements.description.value,published:published.checked,attachments}});chItems=r.items;chRevision=r.revision;changed=false;chEditing=false;dialog.close();notice('准星已保存');showCrosshairs('library')}catch(e){error.textContent=e.message}finally{save.disabled=false}};draw();dialog.append(form);dialog.showModal()}
window.addEventListener('beforeunload',e=>{if(chEditing){e.preventDefault();e.returnValue=''}});setInterval(async()=>{if(staticPreview||page!=='crosshairs'||chTab!=='library'||document.querySelector('#ch-editor').open)return;const old=chRevision;await chFetch();if(old!==chRevision&&page==='crosshairs'&&chTab==='library')chLibrary()},3000);

window.crosshairUnsaved=()=>chEditing;
